@@ -0,0 +1,13 @@
+import { createEventCard } from './event-card.js';
+
+export function orderedEventEntries(events) {
+  return events.map(event => ({
+    event,
+    card: createEventCard(event),
+    timestamp: new Date(event.startsAt).getTime(),
+  })).sort((left, right) => left.timestamp - right.timestamp);
+}
+
+export function buildAgenda(events) {
+  return orderedEventEntries(events).map(({ card }) => card);
+}

