@@ -0,0 +1,11 @@
+import { uniqueBy } from '../lib/collections.js';
+import { normalizeEmail } from '../lib/validation.js';
+
+export function buildRoster(signups) {
+  const normalized = signups.map(({ name, email }) => ({ name: name.trim(), email: normalizeEmail(email) }));
+  return uniqueBy(normalized, ({ email }) => email).sort((left, right) => {
+    if (left.name < right.name) return -1;
+    if (left.name > right.name) return 1;
+    return 0;
+  });
+}

